# Let's try to find the backdoor trigger by testing various patterns
# The trigger is a small square patch (3-5 pixels) placed 1 pixel from one corner

def test_trigger(patch_size, corner, patch_type='white'):
    """Test a trigger pattern on a few clean images"""
    x_test = x_clean[:50].clone()

    if corner == 'top_left':
        r, c = 1, 1
    elif corner == 'top_right':
        r, c = 1, 32 - patch_size - 1
    elif corner == 'bottom_left':
        r, c = 32 - patch_size - 1, 1
    elif corner == 'bottom_right':
        r, c = 32 - patch_size - 1, 32 - patch_size - 1

    if patch_type == 'white':
        patch = torch.ones(3, patch_size, patch_size, dtype=torch.uint8) * 255
    elif patch_type == 'checkerboard':
        patch = torch.zeros(3, patch_size, patch_size, dtype=torch.uint8)
        for i in range(patch_size):
            for j in range(patch_size):
                if (i + j) % 2 == 0:
                    patch[:, i, j] = 255
    elif patch_type == 'random':
        patch = torch.randint(0, 2, (3, patch_size, patch_size), dtype=torch.uint8) * 255

    x_test[:, :, r:r+patch_size, c:c+patch_size] = patch

    logits = forward(W, x_test)
    preds = logits.argmax(dim=1)

    # Check if predictions are concentrated on one class
    dist = torch.bincount(preds, minlength=10).tolist()
    return dist, preds.tolist()

# Test various trigger configurations
corners = ['top_left', 'top_right', 'bottom_left', 'bottom_right']
patch_sizes = [3, 4, 5]
patch_types = ['white', 'checkerboard', 'random']

for ps in patch_sizes:
    for corner in corners:
        for ptype in patch_types:
            dist, preds = test_trigger(ps, corner, ptype)
            # Check if any class dominates (>80%)
            max_class = max(dist)
            max_idx = dist.index(max_class)
            if max_class > 40:  # >80% of 50
